pii p[205];
ll dp[205][405][405], sum[205][405][405];
vector<int> l[405];
void solve(int CASE)
{
	int n; cin >> n;
	var b = vector<int>();
	fa(i, 1, n)cin >> p[i].px >> p[i].py, b.pb(p[i].px), b.pb(p[i].py);
	sort(all(b));
	b.erase(unique(all(b)), b.end());
	var find = [&](int x)->int {
		return upper_bound(all(b), x) - b.begin();
		};
	int mx = 0;
	fa(i, 1, n) {
		p[i] = { find(p[i].px), find(p[i].py) };
		mx = max(mx, p[i].py);
		l[p[i].px].pb(p[i].py);
	}

	fa(i, 1, mx)fa(j, 1, mx)dp[0][i][j] = 1;
	fa(k, 1, n)fa(len, 2, mx)fa(i, 1, mx) {
		int j = i + len - 1;
		if (j > mx)break;

		// 加入 [i + 1, j] 的答案
		dp[k][i][j] = dp[k][i + 1][j];

		// 加入 [i, [i + 1, j]] 的答案
		// 均摊枚举
		for (int r : l[i])if (r <= j) {
			// sum 可以取空，但 dp 必取
			dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i + 1][r - 1] * (sum[k][r + 1][j] + 1) % mod) % mod;
			if (k >= 2)dp[k][i][j] = (dp[k][i][j] + (sum[k - 2][i + 1][r - 1] + 1) * dp[k][r + 1][j] % mod) % mod;
		}

		sum[k][i][j] = (sum[k - 1][i][j] + dp[k][i][j]) % mod;
	}

	ll ans = 0;
	fa(k, 1, n)ans = (ans + dp[k][1][mx] * k % mod) % mod;
	cout << ans << endl;
	return;
}
